final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word0: String): Option[String] = {
    val stripped = if (stripPunctuation) strip(word0) else word0
    val cased = if (lowercase) stripped.toLowerCase else stripped

    val lengthOk = cased.length >= minLength
    if (!lengthOk) return None

    val truncated = maxLength match {
      case Some(m) if cased.length > m => cased.take(m)
      case _ => cased
    }

    Option(truncated).map(_.trim).filter(_.nonEmpty)
  }

  private def strip(word: String): String = {
    @tailrec
    def dropLeading(i: Int): Int = if (i < word.length && punctuation.contains(word.charAt(i))) dropLeading(i + 1) else i

    @tailrec
    def dropTrailing(i: Int): Int = if (i >= 0 && punctuation.contains(word.charAt(i))) dropTrailing(i - 1) else i

    val start = dropLeading(0)
    val end = dropTrailing(word.length - 1)
    if (start > end) "" else word.substring(start, end + 1)
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+")
      .iterator
      .filter(_.nonEmpty)
      .zipWithIndex
      .flatMap { case (word, i) =>
        processToken(word).map { processed =>
          Token(
            value = processed,
            tokenType = TokenType.STRING,
            metadata = Map("position" -> i, "original" -> word)
          )
        }
      }
      .toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").iterator.filter(_.nonEmpty).toList

    var currentPos = 0
    val out = List.newBuilder[(String, Int, Int)]

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        out += ((processed, start, end))
      }

      currentPos = end
    }

    out.result()
  }

  def countTokens(text: String): Int = tokenize(text).size
}

